127	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
128	    @Override
129	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
130	        List<String> missingFields = new ArrayList<>();
131	        requireNonBlank(missingFields, "firstName", ownerFieldsDto.getFirstName());
132	        requireNonBlank(missingFields, "lastName", ownerFieldsDto.getLastName());
133	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
134	        requireNonBlank(missingFields, "address", normalizedAddress);
135	        requireNonBlank(missingFields, "city", ownerFieldsDto.getCity());
136	        requireNonBlank(missingFields, "telephone", ownerFieldsDto.getTelephone());
137	        if (!missingFields.isEmpty()) {
138	            throw new MissingRequiredFieldsException(missingFields);
139	        }
140	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
141	        validateRegistrationDate(ownerFieldsDto.getRegistrationDate());
142	        LocalDate suppliedOrDefaultDate = ownerFieldsDto.getRegistrationDate() != null
143	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
144	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
145	        requireDailyLimitNotReached(registrationDate);
146	        requireCityBelowCapacity(ownerFieldsDto.getCity());
147	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
148	        ownerFieldsDto.setTelephone(normalizedTelephone);
149	        if (ownerFieldsDto.getEmail() != null) {
150	            ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
151	        }
152	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
153	        HttpHeaders headers = new HttpHeaders();
154	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
155	        owner.setAddress(normalizedAddress);
156	        owner.setRegistrationDate(registrationDate);
157	        owner.setCustomerCode(buildCustomerCode(owner, normalizedTelephone));
158	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
159	        if (sharesHousehold) {
160	            owner.setHouseholdId(householdIdFor(normalizeForHousehold(owner.getLastName()),
161	                householdAddressKey(owner.getAddress())));
162	        }
163	        requireUniqueIdentity(owner);
164	        if (sharesHousehold) {
165	            backfillHousehold(owner.getLastName(), owner.getAddress(), owner.getHouseholdId());
166	        }
167	        this.clinicService.saveOwner(owner);
168	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={}",
169	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
170	            ownerMapper.toMembershipLevel(owner));
171	        OwnerDto ownerDto = toOwnerDtoWithBulkWarning(owner);
172	        headers.setLocation(UriComponentsBuilder.newInstance()
173	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
