270	    /**
271	     * Builds the owner's customer code as {@code '<REGION>-<HASH8>'}, where {@code REGION} is the
272	     * region derived from the owner's postcode (falling back to its city, else {@code 'UNKNOWN'}) via
273	     * {@link OwnerMapper#toRegion}, and {@code HASH8} is the first 8 upper-case hex characters of the
274	     * SHA-256 digest of {@code normalizedTelephone + lastName} (e.g. {@code NSW-1A2B3C4D}). The code
275	     * carries no sequence number: it is a deterministic function of the owner's region and identity.
276	     *
277	     * @param owner the owner being created, with its region-determining postcode and city populated
278	     * @param normalizedTelephone the owner's normalized (E.164) telephone, hashed with the last name
279	     * @return the region-and-hash customer code for the owner being created
280	     */
281	    private String buildCustomerCode(Owner owner, String normalizedTelephone) {
282	        String region = ownerMapper.toRegion(owner);
283	        String hash8 = sha256Hex8(normalizedTelephone + owner.getLastName());
284	        return region + "-" + hash8;
285	    }
286	
287	    /**
288	     * Returns the first 8 upper-case hex characters of the SHA-256 digest of {@code value}'s UTF-8
289	     * bytes. Deterministic, so the same input always yields the same 8-character hash.
290	     */
291	    private static String sha256Hex8(String value) {
292	        try {
293	            byte[] digest = MessageDigest.getInstance("SHA-256")
294	                .digest(value.getBytes(StandardCharsets.UTF_8));
295	            StringBuilder sb = new StringBuilder();
296	            for (byte b : digest) {
297	                sb.append(String.format("%02X", b));
298	            }
299	            return sb.substring(0, 8);
300	        }
301	        catch (NoSuchAlgorithmException e) {
302	            throw new IllegalStateException("SHA-256 not available", e);
303	        }
304	    }
305	
306	    /**
307	     * Counts the existing owners (those already persisted before this create) whose first and last
308	     * names both match the incoming owner's, compared case-insensitively. This snapshot is stored on
309	     * the new owner as its {@code namesakeCount} and echoed back on reads.
310	     *
311	     * @param firstName the incoming owner's first name (already validated non-blank)
312	     * @param lastName the incoming owner's last name (already validated non-blank)
313	     * @return the number of existing namesakes sharing both names case-insensitively
314	     */
315	    private int countNamesakes(String firstName, String lastName) {
316	        return (int) this.clinicService.findAllOwners().stream()
317	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
318	                && lastName.equalsIgnoreCase(existing.getLastName()))
319	            .count();
320	    }
