322	    /**
323	     * Records {@code fieldName} as missing when {@code value} is {@code null} or blank (empty or
324	     * whitespace-only), so the caller can reject the request listing every offending field.
325	     */
326	    private static void requireNonBlank(List<String> missingFields, String fieldName, String value) {
327	        if (value == null || value.isBlank()) {
328	            missingFields.add(fieldName);
329	        }
330	    }
331	
332	    /**
333	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. When the
334	     * value carries a leading {@code '+'} its country code is kept; otherwise a {@code '+61'} country
335	     * code is assumed and a single leading {@code '0'} is dropped from the national digits. The result
336	     * must be a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} becomes
337	     * {@code "+61412345678"}.
338	     *
339	     * @param telephone the raw telephone value from the request
340	     * @return the normalized E.164 telephone number (a {@code '+'} followed by 8 to 15 digits)
341	     * @throws InvalidFieldValueException if the value cannot form a valid E.164 number
342	     */
343	    private static String normalizeTelephone(String telephone) {
344	        String e164 = toE164(telephone);
345	        if (e164 == null) {
346	            throw new InvalidFieldValueException("telephone",
347	                "Telephone must be a valid E.164 number ('+' followed by 8 to 15 digits)");
348	        }
349	        return e164;
350	    }
351	
352	    /**
353	     * Converts a raw telephone value to E.164 form, or returns {@code null} when it cannot form a
354	     * valid E.164 number. Used both to normalize incoming values and to compare against existing
355	     * owners' stored numbers when detecting duplicates.
356	     */
357	    private static String toE164(String telephone) {
358	        if (telephone == null) {
359	            return null;
360	        }
361	        String cleaned = telephone.trim().replaceAll("[\\s\\-()]", "");
362	        String digits;
363	        if (cleaned.startsWith("+")) {
364	            digits = cleaned.substring(1);
365	        } else {
366	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
367	            digits = "61" + national;
368	        }
369	        if (!digits.matches("[0-9]{8,15}")) {
370	            return null;
371	        }
372	        if (!hasValidNationalLength(digits)) {
373	            return null;
374	        }
375	        return "+" + digits;
376	    }
377	
378	    /**
379	     * Checks the national-number length against the country code for the country codes that pin one.
380	     * A {@code '+61'} (Australia) number must carry exactly 9 national digits and a {@code '+1'}
381	     * (NANP) number exactly 10; every other country code is accepted on the general 8-to-15-digit
382	     * rule alone. {@code digits} is the E.164 digit string without the leading {@code '+'}.
383	     */
384	    private static boolean hasValidNationalLength(String digits) {
385	        if (digits.startsWith("61")) {
386	            return digits.length() - 2 == 9;
387	        }
388	        if (digits.startsWith("1")) {
389	            return digits.length() - 1 == 10;
390	        }
391	        return true;
392	    }
393	
394	    /**
395	     * Validates and normalizes an owner's email address. A syntactically valid address is required;
396	     * the value is returned lower-cased so it is stored and echoed back in canonical form.
397	     *
398	     * @param email the raw email value from the request (already known to be non-null)
399	     * @return the lower-cased email to be stored and returned
400	     * @throws InvalidFieldValueException if the value is not a syntactically valid email address
401	     */
402	    private static String normalizeEmail(String email) {
403	        String trimmed = email.trim();
404	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
405	            throw new InvalidFieldValueException("email", "Email must be a syntactically valid address");
406	        }
407	        return trimmed.toLowerCase(Locale.ROOT);
408	    }
409	
410	    /** The maximum number of owners permitted in a single city; the {@code (50 + 1)}th is rejected. */
411	    private static final int MAX_OWNERS_PER_CITY = 50;
412	
413	    /**
414	     * Rejects the request when the owner's city already contains {@link #MAX_OWNERS_PER_CITY} or more
415	     * owners, comparing city names case-insensitively. Callers reach this only once {@code city} has
416	     * been validated non-blank.
417	     *
418	     * @param city the incoming owner's city (already validated non-blank)
419	     * @throws CityAtCapacityException if the city is already at or above its owner capacity
420	     */
421	    /** The maximum number of owners that may be registered in a single day; the {@code (100 + 1)}th is rejected. */
422	    private static final int MAX_OWNERS_PER_DAY = 100;
423	
424	    /**
425	     * Rejects the request when {@link #MAX_OWNERS_PER_DAY} or more owners have already been registered
426	     * on {@code businessDay}, counting existing owners whose {@code registrationDate} equals that date.
427	     * New owners take {@code businessDay} as their {@code registrationDate} (the supplied or defaulted
428	     * date rolled forward to a business day), so this caps the number that may be created per day.
429	     *
430	     * @param businessDay the adjusted business-day registration date of the owner being created
431	     * @throws DailyOwnerLimitException if the daily owner-creation limit has already been reached
432	     */
433	    /**
434	     * The number of owners for a single day beyond which the {@code bulkSignupWarning} flag is
435	     * raised; the warning is true once <em>more than</em> this many owners share a registration date.
436	     */
437	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
438	
439	    /**
440	     * Maps {@code owner} to its DTO and sets the {@code bulkSignupWarning} flag: {@code true} when
441	     * more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for this
442	     * owner's registration date, otherwise {@code false}.
443	     *
444	     * @param owner the owner to map
445	     * @return the owner DTO with its bulk-signup warning flag populated
446	     */
447	    private OwnerDto toOwnerDtoWithBulkWarning(Owner owner) {
448	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
449	        ownerDto.setBulkSignupWarning(exceedsBulkSignupThreshold(owner.getRegistrationDate()));
450	        return ownerDto;
451	    }
452	
453	    /**
454	     * Returns whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been
455	     * created on {@code registrationDate}, counting existing owners whose {@code registrationDate}
456	     * equals that date. Returns {@code false} when {@code registrationDate} is {@code null}.
457	     */
458	    private boolean exceedsBulkSignupThreshold(LocalDate registrationDate) {
459	        if (registrationDate == null) {
460	            return false;
461	        }
462	        long registeredThatDay = this.clinicService.findAllOwners().stream()
463	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
464	            .count();
465	        return registeredThatDay > BULK_SIGNUP_WARNING_THRESHOLD;
466	    }
467	
468	    private void requireDailyLimitNotReached(LocalDate businessDay) {
469	        long registeredThatDay = this.clinicService.findAllOwners().stream()
470	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
471	            .count();
472	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
473	            throw new DailyOwnerLimitException(MAX_OWNERS_PER_DAY);
474	        }
475	    }
476	
477	    /**
478	     * Rolls {@code date} forward to a business day: when it falls on a Saturday or Sunday it advances
479	     * to the following Monday; a weekday is returned unchanged. Applied to the effective registration
480	     * date (whether supplied in the request or defaulted to the server date) so a weekend registration
481	     * is recorded on the next business day, and every value derived from the registration date uses the
482	     * adjusted date.
483	     *
484	     * @param date the effective registration date (supplied or defaulted), never {@code null}
485	     * @return the same date, or the next Monday when {@code date} is a weekend
486	     */
487	    private static LocalDate toBusinessDay(LocalDate date) {
488	        DayOfWeek day = date.getDayOfWeek();
489	        if (day == DayOfWeek.SATURDAY) {
490	            return date.plusDays(2);
491	        }
492	        if (day == DayOfWeek.SUNDAY) {
493	            return date.plusDays(1);
494	        }
495	        return date;
496	    }
497	
498	    /** Matches a well-formed postcode: exactly four decimal digits. */
499	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
500	
501	    /**
502	     * Fixed region-to-postcode range table: each region admits an inclusive 4-digit range
503	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). Regions are derived
504	     * from the owner's city via {@link OwnerMapper#CITY_REGION}; a city with no known region is not
505	     * present here and accepts any well-formed postcode.
506	     */
507	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
508	        "NSW", new int[] {2000, 2099},
509	        "VIC", new int[] {3000, 3099},
510	        "QLD", new int[] {4000, 4099});
511	
512	    /**
513	     * Validates an owner's optional {@code postcode}. When absent nothing is checked (postcode is
514	     * optional, so the request contract stays backward-compatible). When present it must be exactly
515	     * four digits and, for a city whose region is known, fall within that region's inclusive range
516	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); a city with no known region accepts any 4-digit
517	     * postcode. A malformed or out-of-range value is rejected with a 400.
518	     *
519	     * @param postcode the raw postcode from the request (may be {@code null} when not supplied)
520	     * @param city the owner's city, used to look up the region whose range constrains the postcode
521	     * @throws InvalidFieldValueException if the postcode is present but malformed or out of range
522	     */
523	    private void validatePostcode(String postcode, String city) {
524	        if (postcode == null) {
525	            return;
526	        }
527	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
528	            throw new InvalidFieldValueException("postcode", "Postcode must be exactly four digits");
529	        }
530	        String region = OwnerMapper.CITY_REGION.getOrDefault(city, "UNKNOWN");
531	        int[] range = REGION_POSTCODES.get(region);
532	        if (range == null) {
533	            return;
534	        }
535	        int value = Integer.parseInt(postcode);
536	        if (value < range[0] || value > range[1]) {
537	            throw new InvalidFieldValueException("postcode",
538	                "Postcode must be valid for the city's region " + region);
539	        }
540	    }
541	
542	    /**
543	     * Validates an owner's optional {@code registrationDate}. When absent nothing is checked (the
544	     * date defaults to the server date). When present it must not be later than the current server
545	     * date: a registration cannot be recorded in the future, so a future date is rejected with a 400.
546	     *
547	     * @param registrationDate the supplied registration date (may be {@code null} when not supplied)
548	     * @throws InvalidFieldValueException if the supplied date is later than the server date
549	     */
550	    private void validateRegistrationDate(LocalDate registrationDate) {
551	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
552	            throw new InvalidFieldValueException("registrationDate",
553	                "Registration date must not be later than the current date");
554	        }
555	    }
556	
557	    private void requireCityBelowCapacity(String city) {
558	        long cityOwners = this.clinicService.findAllOwners().stream()
559	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
560	            .count();
561	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
562	            throw new CityAtCapacityException(city);
563	        }
564	    }
565	
566	    /**
567	     * Rejects the request when the incoming owner's derived {@code identityKey} exactly matches that
568	     * of any existing owner. The key ({@code normalizedTelephone + '|' + (email or empty) + '|' +
569	     * (householdId or empty)}) is the single consolidated duplicate-detection key that replaces the
570	     * former separate telephone, email and household checks. Because the telephone is part of the
571	     * key, two members of the same household (same {@code householdId}) with different telephones
572	     * have different keys and are both allowed; only an exact full-key match is a duplicate. The key
573	     * is derived identically for the incoming and existing owners via {@link OwnerMapper#toIdentityKey}.
574	     *
575	     * @param owner the incoming owner, with its normalized telephone, email and household identifier
576	     *              already populated
577	     * @throws DuplicateIdentityException if another owner already has this exact identity key
578	     */
579	    private void requireUniqueIdentity(Owner owner) {
580	        String identityKey = ownerMapper.toIdentityKey(owner);
581	        boolean taken = this.clinicService.findAllOwners().stream()
582	            .map(ownerMapper::toIdentityKey)
583	            .anyMatch(identityKey::equals);
584	        if (taken) {
585	            throw new DuplicateIdentityException(identityKey);
586	        }
587	    }
588	
589	    /**
590	     * Normalizes a value for household-duplicate comparison: trims leading and trailing whitespace,
591	     * collapses every internal run of whitespace to a single space, and lower-cases the result so
592	     * comparisons are case-insensitive.
593	     */
594	    private static String normalizeForHousehold(String value) {
595	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
596	    }
597	
598	    /**
599	     * Normalizes an owner's address to its canonical stored form: leading and trailing whitespace is
600	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
601	     * upper-cased, and common street-type abbreviations are expanded on a whole-word basis
602	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or whitespace-only
603	     * value normalizes to the empty string, so the required-field check rejects an address that is
604	     * blank once normalized. For example {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
605	     *
606	     * @param address the raw address value from the request (may be {@code null})
607	     * @return the normalized address, or the empty string when blank after normalization
608	     */
609	    private static String normalizeAddress(String address) {
610	        if (address == null) {
611	            return "";
612	        }
613	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
614	        if (collapsed.isEmpty()) {
615	            return "";
616	        }
617	        String[] tokens = collapsed.split(" ");
618	        StringBuilder sb = new StringBuilder();
619	        for (String token : tokens) {
620	            String expanded = switch (token) {
621	                case "ST" -> "STREET";
622	                case "RD" -> "ROAD";
623	                case "AVE" -> "AVENUE";
624	                default -> token;
625	            };
626	            if (sb.length() > 0) {
627	                sb.append(' ');
628	            }
629	            sb.append(expanded);
630	        }
631	        return sb.toString();
632	    }
633	
634	    /**
635	     * Derives the comparison key for an address used by household-duplicate detection and the shared
636	     * household identifier: the address is first put in its canonical normalized form and then
637	     * lower-cased and whitespace-collapsed, so every comparison and the derived id agree on the
638	     * normalized address regardless of the raw casing, spacing or abbreviations supplied.
639	     */
640	    private static String householdAddressKey(String address) {
641	        return normalizeForHousehold(normalizeAddress(address));
642	    }
643	
644	    /**
645	     * Back-fills the shared {@code householdId} onto every existing member of the household
646	     * identified by this last name and address (same normalized last name and address) that does not
647	     * already carry it, so the whole household agrees on the identifier. Members that predate this
648	     * feature (or were created without opting in) are updated to the shared value. Called only after
649	     * the joining owner has passed the identity check, so a rejected request leaves existing owners
650	     * untouched.
651	     *
652	     * @param lastName the joining owner's last name (already validated non-blank)
653	     * @param address the joining owner's address (already validated non-blank)
654	     * @param householdId the shared household identifier for this last name and address
655	     */
656	    private void backfillHousehold(String lastName, String address, String householdId) {
657	        String normalizedLastName = normalizeForHousehold(lastName);
658	        String normalizedAddress = householdAddressKey(address);
659	        this.clinicService.findAllOwners().stream()
660	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
661	                && householdAddressKey(existing.getAddress()).equals(normalizedAddress))
662	            .filter(existing -> !householdId.equals(existing.getHouseholdId()))
663	            .forEach(existing -> {
664	                existing.setHouseholdId(householdId);
665	                this.clinicService.saveOwner(existing);
666	            });
667	    }
668	
669	    /**
670	     * Derives a stable household identifier from the already-normalized last name and address as the
671	     * upper-cased first 12 hex characters of their SHA-256 digest. Deterministic so the same household
672	     * always maps to the same identifier.
673	     */
674	    private static String householdIdFor(String normalizedLastName, String normalizedAddress) {
675	        try {
676	            byte[] digest = MessageDigest.getInstance("SHA-256")
677	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
678	            StringBuilder sb = new StringBuilder();
679	            for (byte b : digest) {
680	                sb.append(String.format("%02X", b));
681	            }
682	            return sb.substring(0, 12);
683	        }
684	        catch (NoSuchAlgorithmException e) {
685	            throw new IllegalStateException("SHA-256 not available", e);
686	        }
687	    }
688	}
